-- Greater San Diego Step 2 — APPLY. Writes to the SHARED database (staging AND Production).
-- GENERATED by operator-admin/scripts/buildGreaterSanDiegoCitiesSql.ts from
-- src/lib/geo/rosters/greaterSanDiego.ts — edit the roster and regenerate; never hand-edit.
-- Run ONLY after Wayne's explicit approval, after step2-cities-preflight.sql shows the expected state:
--   supabase db query --linked -f docs/operations/greater-san-diego/step2-cities-apply.sql
-- One transaction. Inserts 41 cities into Greater San Diego (status active,
-- supports_neighbourhoods false). Every guard RAISEs (rolling back everything) unless the
-- market and Solana Beach are exactly as Step 1 left them and none of the new slugs exist.
-- Touches no market row (default city stays solana-beach), no existing city, no venue
-- (Encore Sushi untouched), no other market.
-- Centers: US Census 2024 Gazetteer internal points (public domain); NULL where the
-- Gazetteer has no place record. display_order follows the roster (Solana Beach keeps 1).
BEGIN;

DO $$
DECLARE n integer; m_id uuid;
BEGIN
  SELECT id INTO m_id FROM public.markets
   WHERE slug = 'greater-san-diego' AND status = 'active' AND country = 'US' AND province = 'CA';
  IF m_id IS NULL THEN RAISE EXCEPTION 'greater-san-diego market missing or changed — nothing applied'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.markets WHERE id = m_id AND default_city_id = '22ee8a97-ae30-4eb0-92ce-ca456cb5bbdd') THEN
    RAISE EXCEPTION 'default city is no longer solana-beach — nothing applied';
  END IF;

  SELECT count(*) INTO n FROM public.cities WHERE market_id = m_id;
  IF n <> 1 THEN RAISE EXCEPTION 'expected exactly 1 existing city (solana-beach), found % — nothing applied', n; END IF;

  SELECT count(*) INTO n FROM public.cities WHERE market_id = m_id AND slug = ANY(ARRAY['san-diego', 'oceanside', 'carlsbad', 'encinitas', 'del-mar', 'rancho-santa-fe', 'escondido', 'san-marcos', 'vista', 'poway', 'fallbrook', 'bonsall', 'valley-center', 'pala', 'pauma-valley', 'ramona', 'chula-vista', 'coronado', 'national-city', 'imperial-beach', 'bonita', 'la-mesa', 'el-cajon', 'santee', 'lemon-grove', 'spring-valley', 'lakeside', 'alpine', 'jamul', 'julian', 'borrego-springs', 'descanso', 'pine-valley', 'mount-laguna', 'campo', 'potrero', 'dulzura', 'boulevard', 'jacumba-hot-springs', 'warner-springs', 'santa-ysabel']::text[]);
  IF n <> 0 THEN RAISE EXCEPTION '% new city slug(s) already exist — nothing applied', n; END IF;

  INSERT INTO public.cities (market_id, slug, name, status, supports_neighbourhoods, display_order, center_lat, center_lng)
  SELECT m_id, v.slug, v.name, 'active', false, v.display_order, v.center_lat, v.center_lng
    FROM (VALUES
    ('san-diego', 'San Diego', 2, 32.815, -117.1356),
    ('oceanside', 'Oceanside', 3, 33.2246, -117.3063),
    ('carlsbad', 'Carlsbad', 4, 33.1293, -117.2842),
    ('encinitas', 'Encinitas', 5, 33.0506, -117.2636),
    ('del-mar', 'Del Mar', 6, 32.9639, -117.2598),
    ('rancho-santa-fe', 'Rancho Santa Fe', 7, 33.0258, -117.1981),
    ('escondido', 'Escondido', 8, 33.1331, -117.074),
    ('san-marcos', 'San Marcos', 9, 33.1326, -117.1699),
    ('vista', 'Vista', 10, 33.1895, -117.2386),
    ('poway', 'Poway', 11, 32.9877, -117.0218),
    ('fallbrook', 'Fallbrook', 12, 33.3742, -117.2204),
    ('bonsall', 'Bonsall', 13, 33.2749, -117.1919),
    ('valley-center', 'Valley Center', 14, 33.233, -117.0158),
    ('pala', 'Pala', 15, 33.3639, -117.0678),
    ('pauma-valley', 'Pauma Valley', 16, NULL, NULL),
    ('ramona', 'Ramona', 17, 33.0458, -116.8775),
    ('chula-vista', 'Chula Vista', 18, 32.6277, -117.0152),
    ('coronado', 'Coronado', 19, 32.6576, -117.1565),
    ('national-city', 'National City', 20, 32.6659, -117.0974),
    ('imperial-beach', 'Imperial Beach', 21, 32.5691, -117.1149),
    ('bonita', 'Bonita', 22, 32.6732, -117.0061),
    ('la-mesa', 'La Mesa', 23, 32.7695, -117.0219),
    ('el-cajon', 'El Cajon', 24, 32.8017, -116.9605),
    ('santee', 'Santee', 25, 32.855, -116.9861),
    ('lemon-grove', 'Lemon Grove', 26, 32.7331, -117.0344),
    ('spring-valley', 'Spring Valley', 27, 32.7299, -116.9764),
    ('lakeside', 'Lakeside', 28, 32.8566, -116.9042),
    ('alpine', 'Alpine', 29, 32.8425, -116.7559),
    ('jamul', 'Jamul', 30, 32.7184, -116.8709),
    ('julian', 'Julian', 31, 33.0735, -116.5889),
    ('borrego-springs', 'Borrego Springs', 32, 33.241, -116.3571),
    ('descanso', 'Descanso', 33, 32.8696, -116.6279),
    ('pine-valley', 'Pine Valley', 34, 32.8415, -116.5107),
    ('mount-laguna', 'Mount Laguna', 35, 32.8711, -116.4247),
    ('campo', 'Campo', 36, 32.641, -116.4745),
    ('potrero', 'Potrero', 37, 32.6131, -116.6068),
    ('dulzura', 'Dulzura', 38, NULL, NULL),
    ('boulevard', 'Boulevard', 39, 32.664, -116.2896),
    ('jacumba-hot-springs', 'Jacumba Hot Springs', 40, 32.6365, -116.1907),
    ('warner-springs', 'Warner Springs', 41, NULL, NULL),
    ('santa-ysabel', 'Santa Ysabel', 42, NULL, NULL)
    ) AS v(slug, name, display_order, center_lat, center_lng);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 41 THEN RAISE EXCEPTION 'expected 41 cities inserted, got %', n; END IF;

  SELECT count(*) INTO n FROM public.cities WHERE market_id = m_id;
  IF n <> 42 THEN RAISE EXCEPTION 'expected 42 cities in market, found %', n; END IF;
END $$;

-- Verification (printed by the CLI): 42 active cities, default still solana-beach,
-- Encore still in solana-beach and unchanged.
SELECT m.slug AS market, dc.slug AS default_city,
       count(c.*) AS cities, count(c.*) FILTER (WHERE c.status = 'active') AS active_cities,
       (SELECT vc.slug FROM public.venues v JOIN public.cities vc ON vc.id = v.city_id WHERE v.id = '4ecc0d2c-3ef0-4f85-8f34-5b4e079e1840') AS encore_city
  FROM public.markets m
  JOIN public.cities c ON c.market_id = m.id
  LEFT JOIN public.cities dc ON dc.id = m.default_city_id
 WHERE m.slug = 'greater-san-diego'
 GROUP BY m.slug, dc.slug;

COMMIT;
